// Client requests a new access token:
POST /oauth/token
Content-Type: application/x-www-form-urlencoded

grant_type=refresh_token
&refresh_token=eyJhbGciOi...

// Server response:
{
  "access_token": "new-access-token",
  "expires_in": 900,
  "refresh_token": "new-rotated-refresh-token",
  "token_type": "Bearer"
}

public record RefreshTokenFamily(
    Guid Id,
    string UserId,
    string CurrentTokenHash,
    DateTimeOffset CreatedAt,
    DateTimeOffset? RevokedAt
);

app.MapPost("/oauth/token", async (TokenRequest req, AppDbContext db) =>
{
    if (req.GrantType != "refresh_token")
        return Results.BadRequest();

    var tokenHash = SHA256.HashData(Encoding.UTF8.GetBytes(req.RefreshToken));
    var family = await db.RefreshTokenFamilies
        .FirstOrDefaultAsync(f => f.CurrentTokenHash == tokenHash
                               && f.RevokedAt == null);

    if (family == null)
    {
        // Token not found — possible theft of an old token
        await RevokeEntireFamilyAsync(db, req.RefreshToken);
        return Results.BadRequest(new { error = "invalid_grant" });
    }

    // Rotate: generate new token and replace the hash
    var newRefreshToken = GenerateSecureToken();
    var newHash = SHA256.HashData(Encoding.UTF8.GetBytes(newRefreshToken));
    family.CurrentTokenHash = newHash;
    await db.SaveChangesAsync();

    var accessToken = GenerateAccessToken(family.UserId);
    return Results.Ok(new
    {
        access_token = accessToken,
        expires_in = 900,
        refresh_token = newRefreshToken
    });
});

async function refreshAccessToken() {
  const response = await fetch('/oauth/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      grant_type: 'refresh_token',
      refresh_token: 'the-cookie-is-sent-automatically'
    }),
    credentials: 'same-origin'
  });

  if (!response.ok) {
    // Token was rejected — redirect to login
    window.location.href = '/login';
    return;
  }

  const data = await response.json();
  // Store access token in memory only (not localStorage)
  window.accessToken = data.access_token;
}
